float sdSquircle(vec2 p, float n) {
    // symmetries
    p = abs(p); if (p.y>p.x) p=p.yx;

    n = 2.0/n;// note the remapping in order to match the implicit versions

    float xa = 0.0, xb = 6.283185/8.0;
    for (int i=0; i < 6; i++) {
        float x = 0.5*(xa+xb);
        float c = cos(x);
        float s = sin(x);
        float cn = pow(c, n);
        float sn = pow(s, n);
        float y = (p.x-cn)*cn*s*s - (p.y-sn)*sn*c*c;

        if (y < 0.0) xa = x; else xb = x;
    }
    // compute distance
    vec2  qa = pow(vec2(cos(xa), sin(xa)), vec2(n));
    vec2  qb = pow(vec2(cos(xb), sin(xb)), vec2(n));
    vec2  pa = p-qa, ba = qb-qa;
    float h = clamp(dot(pa, ba)/dot(ba, ba), 0.0, 1.0);
    return length(pa - ba*h) * sign(pa.x*ba.y-pa.y*ba.x);
}

float approx_sdSquircle(vec2 p, float n) {
    // symmetries
    p = abs(p); if (p.y>p.x) p=p.yx;

    float w = pow(p.x, n) + pow(p.y, n);

    // implicit
    // return pow(w,1.0/n) - 1.0;

    // linearlized implicit (taylor)
    float b = 2.0*n-2.0;
    float a = 1.0-1.0/n;
    return (w-pow(w, a)) * inversesqrt(pow(p.x, b)+pow(p.y, b));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;
    p *= 1.4;
    m *= 1.4;

    // animation
    //float n = 3.0 + 2.5*sin(6.283185*iTime/3.0);
    float n = 2.5;

    // distance
    float d = (p.y < p.x) ? sdSquircle(p, n) :
    approx_sdSquircle(p, n);
    // coloring
    vec3 col = (d > 0.0) ? vec3(0.) : vec3(1.0);
    //col *= 1.0 - exp(-8.0*abs(d));
    //col *= 0.6 + 0.4*smoothstep(-0.5,0.5,cos(90.0*abs(d)));

    col = mix(col, vec3(1.0), 1.0-smoothstep(0.0, 0.015, abs(d)));

    // while touch down
    if (iMouse.z > 0.001) {
        d = (m.y < m.x) ? sdSquircle(m, n) :
        approx_sdSquircle(m, n);
        col = mix(col, vec3(1.0, 1.0, 0.0), 1.0-smoothstep(0.0, 0.005, abs(length(p-m)-abs(d))-0.0025));
        col = mix(col, vec3(1.0, 1.0, 0.0), 1.0-smoothstep(0.0, 0.005, length(p-m)-0.015));
    }

    //col *= smoothstep( 0.005, 0.010, abs(p.y-p.x) );
    fragColor = vec4(col, 1.0);
}
